22	const BASE_PRICE_BY_TYPE: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const FIRST_INSURANCE_MULTIPLIER = 1.1;
32	const CONTRACT_FEE = 5;
33	
34	const BUILDING_BLOCK_SIZE = 3;
35	const BUILDING_BLOCK_BASE_PRICE = 60;
36	
37	const sumOfIndividualPrices = (items: Item[]): number =>
38	  items.reduce((total, item) => total + BASE_PRICE_BY_TYPE[item.type], 0);
39	
40	// "Alike" in the price list means same type — material and enchantment do not
41	// affect whether components group into a building block.
42	const groupByType = (items: Item[]): Item[][] =>
43	  [...new Set(items.map((item) => item.type))].map((type) =>
44	    items.filter((item) => item.type === type),
45	  );
46	
47	// Every three alike components form a building block priced at 60 G; the
48	// remainder of the group is priced individually.
49	const basePriceOfGroup = (group: Item[]): number => {
50	  const blocks = Math.floor(group.length / BUILDING_BLOCK_SIZE);
51	  const leftovers = group.slice(blocks * BUILDING_BLOCK_SIZE);
52	
53	  return blocks * BUILDING_BLOCK_BASE_PRICE + sumOfIndividualPrices(leftovers);
54	};
55	
56	const basePriceOf = (items: Item[]): number =>
57	  groupByType(items).reduce((total, group) => total + basePriceOfGroup(group), 0);
58	
59	// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
60	// no test yet lands on a half-way value, so the rounding *direction* stays
61	// unspecified until the "rounds in MHPCO's favor" test pins it.
62	const quoteStep = (step: Step): StepResult => ({
63	  premium:
64	    Math.round(basePriceOf(step.items!) * FIRST_INSURANCE_MULTIPLIER) + CONTRACT_FEE,
65	});
66	
67	export const runScenario = (scenario: Scenario): ScenarioResult => ({
68	  results: scenario.steps.map(quoteStep),
69	});
